with feeders as (
    select
        md5(upper('LNK_POLICY_PARTY|' || (LNK_POLICY_PARTY_BK__POLICY_NO_EMP_CODE))) as LNK_POLICY_PARTY_HK
        , cast(null as varchar) as PARTY_ROLE_TYPE
        , cast(null as varchar) as ROLE_SEQUENCE
        , EFFECTIVE_DATE as ROLE_EFFECTIVE_DATE
        , STATUS as ROLE_STATUS
        , 'BJAZ_HAT_POL_EMP_MAP' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_pol_emp_map') }}
    where (LNK(HUB_POLICY = nullif(trim(POLICY_NO),''), HUB_PARTY = nullif('EMP:' || coalesce(nullif(trim(POLICY_NO),''),'') || '#' || coalesce(nullif(trim(EMP_CODE),''),''), 'EMP:#'))) is not null
    union all
    select
        md5(upper('LNK_POLICY_PARTY|' || (LNK_POLICY_PARTY_BK__CONTRACT_ID_PARTNER_ID))) as LNK_POLICY_PARTY_HK
        , 'INTERESTED_PARTY' as PARTY_ROLE_TYPE
        , coalesce(nullif(trim(IP_NO), ''), '') as ROLE_SEQUENCE
        , cast(null as varchar) as ROLE_EFFECTIVE_DATE
        , cast(null as varchar) as ROLE_STATUS
        , 'OCP_INTERESTED_PARTIES' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ocp_interested_parties') }}
    where (LNK(HUB_POLICY = nullif(trim(CONTRACT_ID),''), HUB_PARTY = nullif('PARTNER:' || nullif(trim(PARTNER_ID),''), 'PARTNER:'))) is not null
),

resolved as (
    select
        LNK_POLICY_PARTY_HK,
        PARTY_ROLE_TYPE,
        ROLE_SEQUENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then ROLE_EFFECTIVE_DATE end) as ROLE_EFFECTIVE_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then ROLE_STATUS end) as ROLE_STATUS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by LNK_POLICY_PARTY_HK, PARTY_ROLE_TYPE, ROLE_SEQUENCE
),

hashed as (
    select
        *,
        case when PARTY_ROLE_TYPE is not null or ROLE_SEQUENCE is not null or ROLE_EFFECTIVE_DATE is not null or ROLE_STATUS is not null
                     then md5(upper(coalesce(cast(PARTY_ROLE_TYPE as varchar), '') || '|' || coalesce(cast(ROLE_SEQUENCE as varchar), '') || '|' || coalesce(cast(ROLE_EFFECTIVE_DATE as varchar), '') || '|' || coalesce(cast(ROLE_STATUS as varchar), '')))
                end as SAT_LNK_POLICY_PARTY_ROLE_HASHDIFF
    from resolved
)

select * from hashed
where LNK_POLICY_PARTY_HK is not null
  and SAT_LNK_POLICY_PARTY_ROLE_HASHDIFF is not null
